 return leads.slice(6).map((lead, i) => ({
  json: { ...lead, email: `test${i + 1}@example.com`, eingegangenAm: "" }
}));

const lead = $('Lead normalisieren').item.json;
const roh = $input.item.json.output?.[0]?.content?.[0]?.text;

let ki = roh;
if (typeof roh === "string") {
  try {
    ki = JSON.parse(roh);
  } catch (e) {
    ki = null;
  }
}

const erlaubt = ["hot", "warm", "cold", "spam"];
const gueltig = ki !== null && typeof ki === "object" && erlaubt.includes(ki.kategorie);

return {
  json: {
    ...lead,
    kategorie: gueltig ? ki.kategorie : "manuell_pruefen",
    score: gueltig ? ki.score : null,
    begruendung: gueltig ? ki.begruendung : "KI-Antwort war ungültig"
  }
};

const ergebnisse = $input.all().map(item => item.json);
const antworten = $('Message a model').all().map(item => item.json);
const falsch = ergebnisse.filter(lead => lead.kategorie !== lead.soll);
const treffer = ergebnisse.length - falsch.length;
let inputTokens = 0;
let outputTokens = 0;
for (const a of antworten) {
  inputTokens += a.usage?.input_tokens ?? 0;
  outputTokens += a.usage?.output_tokens ?? 0;
}

const kosten = inputTokens / 1000000 * 0.10 + outputTokens / 1000000 * 0.50;

return [{json: {
  trefferquote: `${treffer} von ${ergebnisse.length}`,
  falsch: falsch.map(lead => `${lead.name}: soll ${lead.soll}, ist ${lead.kategorie} - ${lead.begruendung}`),
  inputTokens,
  outputTokens,
  kostenGesamtUSD: kosten,
  kostenProLeadUSD: kosten / ergebnisse.length
} }];
